/**
 * Canary for #4702: a distinctive keychain value must not appear in generated files, CLI output,
 * logs or a machine envelope. The name stays in Compose as `${NAME}` and is interpolated at run
 * time from the process environment, never written into a file.
 */
import { readdirSync, readFileSync, statSync } from "node:fs";
import { join, relative } from "node:path";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { createTempProject, runCommandInProcess } from "../../test-support/index.js";
import { clearDiscoveryCache } from "../../utils/discovery-context.js";
import type { Keychain } from "../../utils/keychain.js";
import { envSecretValues, redactLogLines } from "../../utils/secret-redaction.js";
import { configCommand } from "../config.js";

const CANARY = "CANARY_9f4b2d_SECRET_VALUE";
const NAME = "CANARY_KEY";

function filesUnder(root: string, dir: string): string[] {
  let entries: string[];
  try {
    entries = readdirSync(dir);
  } catch {
    return [];
  }
  return entries.flatMap((entry) => {
    const path = join(dir, entry);
    return statSync(path).isDirectory() ? filesUnder(root, path) : [relative(root, path)];
  });
}

function fakeKeychain(): Keychain {
  return {
    project: "canary-project",
    platform: "linux",
    get: (name: string) => (name === NAME ? CANARY : undefined),
    set: () => {},
    unset: () => {},
    list: () => [NAME],
  };
}

function project() {
  return createTempProject({
    projectJson: {
      version: "1.0",
      project: { name: "canary-project", version: "1.0.0" },
      phases: Object.fromEntries(
        ["pre_alpha", "alpha", "beta", "out_of_scope"].map((phase) => [
          phase,
          { name: phase, description: "", enabledStacks: [] },
        ]),
      ),
      optional_infra: {
        monitoring: false,
        elk: false,
        debezium: false,
        golden_image: false,
        verdaccio: false,
      },
      discovery: { paths: ["services/*/*"] },
    },
    resources: {
      api: {
        appType: "bring-your-own",
        schemaVersion: 1,
        image: "example/canary:latest",
        port: 8080,
        secrets: { required: [NAME] },
      },
    },
  });
}

describe("secret canary (#4702)", () => {
  beforeEach(() => {
    clearDiscoveryCache();
  });

  it("keeps the value out of regenerated files and the verify JSON envelope", async () => {
    const root = project();
    const regenerate = await runCommandInProcess(configCommand, ["regenerate"], root);
    expect(regenerate.status, regenerate.stdout + regenerate.stderr).toBeUndefined();

    const generated = [
      ...filesUnder(root, join(root, ".flisk", ".flisk-out")),
      ...filesUnder(root, join(root, "services")).filter((path) => path.includes(".autogenerated")),
    ].map((path) => join(root, path));
    expect(generated.length).toBeGreaterThan(0);
    const contents = generated.map((path) => readFileSync(path, "utf-8")).join("\n");
    expect(contents).not.toContain(CANARY);

    // Compose interpolation stays in the engine source; the CLI only exports values into the
    // child process environment, so no value is written into a generated file.
    const envSecrets = readFileSync(
      join(
        __dirname,
        "../../../../runtime/engine/topologies/platform/docker/secrets/env_secrets.star",
      ),
      "utf-8",
    );
    expect(envSecrets).toContain("${" + "{{name}:?");
    expect(envSecrets).toContain("${" + "{{name}:-}}");
    expect(envSecrets).toContain("get_secret_provider() == 'infisical'");

    vi.stubEnv("FLISK_SECRET_PROVIDER", "keychain");
    try {
      const verify = await runCommandInProcess(configCommand, ["verify", "--json"], root);
      expect(verify.stdout + verify.stderr).not.toContain(CANARY);
      expect(verify.stdout).toContain('"schemaVersion"');
    } finally {
      vi.unstubAllEnvs();
    }
  });

  it("masks a keychain value in log output", () => {
    const root = project();
    const env = { FLISK_SECRET_PROVIDER: "keychain" };
    const values = envSecretValues(root, [], { keychain: fakeKeychain(), env });
    expect(values).toContain(CANARY);
    const redacted = redactLogLines([{ resource: "api", text: `token=${CANARY}` }], values);
    expect(redacted[0]?.text).not.toContain(CANARY);
  });
});
